       (COUNT(DISTINCT ?surgery_patient) AS ?patients_surgery)
       (COUNT(DISTINCT ?radiotherapy_patient) AS ?patients_radiotherapy)
       (COUNT(DISTINCT ?both_patient) AS ?patients_both)
       (COUNT(DISTINCT ?no_treatment_patient) AS ?patients_no_treatment)
       (ROUND(AVG(?wait_days)) AS ?avg_wait_days)
WHERE {
  GRAPH ?g {
    ?onco a sphn:OncologyDiagnosis .
    ?onco sphn:hasSubjectPseudoIdentifier ?pid .
    ?onco sphn:hasRecordDateTime ?diagnosis_date .

    OPTIONAL {
      GRAPH ?g {
        ?event a sphn:MedicalProcedure ;
               sphn:hasSubjectPseudoIdentifier ?pid .
        ?event sphn:hasDateTime ?treatment_date .
        ?event sphn:hasCode ?code .
        ?code a sphn:SurgicalProcedure OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        BIND ("Surgery" AS ?treatment_type)
        BIND (?g AS ?surgery_patient)
      }
    }
    OPTIONAL {
      GRAPH ?g {
        ?event a sphn:MedicalProcedure ;
               sphn:hasSubjectPseudoIdentifier ?pid .
        ?event sphn:hasDateTime ?treatment_date .
        ?event sphn:hasCode ?code .
        ?code a sphn:RadiotherapyProcedure OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        BIND ("Radiotherapy" AS ?treatment_type)
        BIND (?g AS ?radiotherapy_patient)
      }
    }
    OPTIONAL {
      GRAPH ?g {
        ?event a sphn:MedicalProcedure ;
               sphn:hasSubjectPseudoIdentifier ?pid .
        ?event sphn:hasDateTime ?treatment_date .
        ?event sphn:hasCode ?code .
        ?code a sphn:SurgicalProcedure OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        ?event sphn:hasCode ?code2 .
        ?code2 a sphn:RadiotherapyProcedure OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        BIND ("Both" AS ?treatment_type)
        BIND (?g AS ?both_patient)
      }
    }
    OPTIONAL {
      GRAPH ?g {
        ?event a sphn:MedicalProcedure ;
               sphn:hasSubjectPseudoIdentifier ?pid .
        ?event sphn:hasDateTime ?treatment_date .
        ?event sphn:hasCode ?code .
        ?code a sphn:MedicalProcedure OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
        FILTER NOT EXISTS {
          ?code a sphn:SurgicalProcedure .
          ?code a sphn:RadiotherapyProcedure .
        }
        BIND ("Other" AS ?treatment_type)
        BIND (?g AS ?no_treatment_patient)
      }
    }
  }
  FILTER EXISTS {
    GRAPH ?g {
      ?event a sphn:MedicalProcedure ;
             sphn:hasSubjectPseudoIdentifier ?pid .
      ?event sphn:hasDateTime ?treatment_date .
      ?event sphn:hasCode ?code .
      ?code a sphn:SurgicalProcedure OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    }
    ||
    GRAPH ?g {

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

SELECT ?duration_category (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?case a sphn:AdministrativeCase .
    OPTIONAL {
      ?dx a sphn:BilledDiagnosis ;
          sphn:hasAdministrativeCase ?case ;
          sphn:hasCode ?dx_code .
      ?dx_code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
      BIND("cholera" AS ?duration_category)
    }
    OPTIONAL {
      ?admin a sphn:DrugAdministrationEvent ;
             sphn:hasAdministrativeCase ?case ;
             sphn:hasDuration ?duration .
      BIND("other" AS ?duration_category)
    }
    FILTER (BOUND(?duration))
  }
}
GROUP BY ?duration_category

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>

SELECT ?sex_label (COUNT(DISTINCT ?g) AS ?patient_count)
WHERE {
  GRAPH ?g {
    ?diagnosis a sphn:BilledDiagnosis ;
               sphn:hasCode ?code .
    ?code a icd-10-gm:A00 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?diagnosis sphn:hasSubjectPseudoIdentifier ?subject .
    ?subject sphn:hasIdentifier ?pseudo_id .
    OPTIONAL {
      ?sex a sphn:AdministrativeSex ;
           sphn:hasSubjectPseudoIdentifier ?subject ;
           sphn:hasCode ?sex_code .
      ?sex_code a ?sex_label .
    }
  }
}
GROUP BY ?sex_label
ORDER BY DESC(?patient_count)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX country: <https://biomedit.ch/rdf/sphn-resource/country/>

SELECT (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
