           sphn:hasSubjectPseudoIdentifier ?subject ;
           sphn:hasCountry ?birth_country .
    ?subject a sphn:SubjectPseudoIdentifier ;
             sphn:hasIdentifier ?pseudo_id .
    ?birth_country a country:Country .
  }
  FILTER NOT EXISTS {
    GRAPH ?g {
      ?subject a sphn:SubjectPseudoIdentifier ;
               sphn:hasIdentifier ?pseudo_id .
      ?birth_country a country:Country ;
                     sphn:hasCountry ?citizen_country .
    }
  }
