PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?route_concept
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?case) AS ?administrations)
       (ROUND(100.0 * COUNT(DISTINCT ?case) / COUNT(DISTINCT ?g)) AS ?pct_match)
WHERE {
  {
    SELECT DISTINCT ?g ?case ?route_code
    WHERE {
      GRAPH ?g {
        ?admin a sphn:DrugAdministrationEvent ;
               sphn:hasAdministrativeCase ?case ;
               sphn:hasAdministrationRouteCode ?route_code .
      }
    }
  }
  {
    SELECT DISTINCT ?g ?case ?route_code
    WHERE {
      GRAPH ?g {
        ?admin2 a sphn:DrugAdministrationEvent ;
                sphn:hasAdministrativeCase ?case ;
                sphn:hasAdministrationRouteCode ?route_code .
      }
    }
  }
  ?route_code a ?route_concept .
  OPTIONAL {
    GRAPH <https://biomedit.ch/rdf/sphn-resource/global> { ?route_concept rdfs:label ?label . }
    FILTER (LANGMATCHES(LANG(?label), "de"))
  }
  FILTER (STRSTARTS(STR(?route_concept), "http://snomed.info/id/"))
}
GROUP BY ?route_concept
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?route_concept
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?case) AS ?administrations)
       (COUNT(DISTINCT ?case) AS ?matches)
       (ROUND(100.0 * ?matches / ?administrations) AS ?percentage)
WHERE {
  {
    SELECT DISTINCT ?g ?case ?prescribed_route ?actual_route
    WHERE {
      GRAPH ?g {
        ?prescription a sphn:DrugAdministrationEvent ;
                      sphn:hasAdministrativeCase ?case ;
                      sphn:hasAdministrationRouteCode ?prescribed_route .
        ?actual a sphn:DrugAdministrationEvent ;
                sphn:hasAdministrativeCase ?case ;
                sphn:hasAdministrationRouteCode ?actual_route .
      }
    }
  }
  OPTIONAL {
    GRAPH ?route_concept {
      ?prescribed_route a ?route_concept .
      ?actual_route a ?route_concept .
    }
    OPTIONAL {
      GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
        ?route_concept rdfs:label ?label .
      }
      FILTER (LANGMATCHES(LANG(?label), "de"))
    }
  }
  FILTER (BOUND(?route_concept))
}
GROUP BY ?route_concept
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX bif: <bif:>

SELECT ?procedure_concept
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?procedure) AS ?procedures)
       (ROUND(1000.0 * SUM(?is_main) / COUNT(?procedure)) / 10 AS ?main_procedure_pct)
       (ROUND(AVG(?duration_minutes)) AS ?avg_duration_minutes)
WHERE {
  GRAPH ?g {
    ?procedure a sphn:TherapeuticUltrasoundProcedure ;
               sphn:hasCode ?code ;
               sphn:hasDuration ?duration ;
               sphn:hasAdministrativeCase ?case .
    ?code a ?procedure_concept .
    ?case a sphn:AdministrativeCase ;
          sphn:hasMainProcedure ?main_proc .
  }
  BIND (IF(?main_proc = ?procedure, 1, 0) AS ?is_main)
  BIND (bif:datediff("minute", ?duration, ?duration) AS ?duration_minutes)
}
GROUP BY ?procedure_concept
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX bif: <bif:>

SELECT ?method (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?start_in_hospital) AS ?start_in_hospital_count)
       (ROUND(AVG(?duration_days)) AS ?avg_duration_days)
WHERE {
  GRAPH ?g {
    ?drug_event a sphn:BilledProcedure ;
                sphn:hasCode ?code .
    ?code a ?concept .
  }
  OPTIONAL {
    GRAPH ?g {
      ?concept rdfs:label ?label .
    }
    FILTER (LANGMATCHES(LANG(?label), "de"))
  }
  BIND (REPLACE(STR(?concept), "^.*/", "") AS ?method)
  FILTER (REGEX(?method, "^[0-9]+$"))
  OPTIONAL {
    GRAPH ?g {
      ?drug_event sphn:hasStartDateTime ?start .
      ?drug_event sphn:hasEndDateTime ?end .
      BIND (bif:datediff("day", ?start, ?end) AS ?duration_days)
    }
  }
  OPTIONAL {
    GRAPH ?g {
      ?drug_event sphn:hasRank sphn-individual:Principal .
      BIND(?g AS ?start_in_hospital)
    }
  }
}
GROUP BY ?method
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?variant (SAMPLE(?label) AS ?variant_name)
       (COUNT(DISTINCT ?g) AS ?patients)
       (COUNT(DISTINCT ?het_patient) AS ?patients_heterozygous)
       (COUNT(DISTINCT ?hom_patient) AS ?patients_homozygous)
       (COUNT(DISTINCT ?cancer_patient) AS ?patients_with_cancer)
WHERE {
  GRAPH ?g {
    ?record a sphn:GeneticVariation ;
            sphn:hasCode ?code .
    ?code a ?concept OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
  OPTIONAL {
    GRAPH <https://biomedit.ch/rdf/sphn-resource/global> { ?concept rdfs:label ?label . }
  }
  OPTIONAL {
    GRAPH ?g {
      ?record sphn:hasAlleleCount ?count .
      BIND (IF(?count = 2, ?g, NULL) AS ?hom_patient)
      BIND (IF(?count = 1, ?g, NULL) AS ?het_patient)
    }
  }
  OPTIONAL {
    GRAPH ?cancer_patient {
      ?cancer_record a sphn:OncologyDiagnosis .
    }
  }
}
GROUP BY ?variant ?variant_name
ORDER BY DESC(?patients)

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?outcome_type (COUNT(DISTINCT ?g) AS ?patients)
WHERE {
  GRAPH ?g {
    ?event a sphn:AdverseEvent ;
           sphn:hasSeverityCode ?severity_code .
    ?severity_code a ?severity .
  }
  FILTER (STRSTARTS(STR(?severity), "http://snomed.info/id/"))
  FILTER (REGEX(STR(?severity), "serious|life-threatening|fatal|death", "i"))

  OPTIONAL {
    GRAPH ?g {
      ?event sphn:hasOutcomeCode ?outcome_code .
      ?outcome_code a ?outcome .
    }
    FILTER (STRSTARTS(STR(?outcome), "http://snomed.info/id/"))
    BIND (IF(STRSTARTS(STR(?outcome), "http://snomed.info/id/268441000"), "Death",
             IF(STRSTARTS(STR(?outcome), "http://snomed.info/id/37103007"), "Full Recovery",
                "Other")) AS ?outcome_type)
  }
  OPTIONAL {
    GRAPH ?g {
      ?event sphn:hasOutcomeCode ?outcome_code .
      ?outcome_code a ?outcome .
    }
    FILTER (STRSTARTS(STR(?outcome), "http://snomed.info/id/268441000"))
    BIND ("Death" AS ?outcome_type)
  }
  OPTIONAL {
    GRAPH ?g {
      ?event sphn:hasOutcomeCode ?outcome_code .
      ?outcome_code a ?outcome .
    }
    FILTER (STRSTARTS(STR(?outcome), "http://snomed.info/id/37103007"))
    BIND ("Full Recovery" AS ?outcome_type)
  }
}
GROUP BY ?outcome_type
ORDER BY ?outcome_type

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX snomed: <http://snomed.info/id/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT (COUNT(DISTINCT ?g) AS ?total_babies)
       (COUNT(DISTINCT ?early_baby) AS ?early_babies)
       (COUNT(DISTINCT ?vaginal_early) AS ?vaginal_early)
       (COUNT(DISTINCT ?cesarean_early) AS ?cesarean_early)
       (ROUND(1000.0 * COUNT(DISTINCT ?early_baby) / COUNT(DISTINCT ?g)) / 10 AS ?pct_early)
       (ROUND(1000.0 * COUNT(DISTINCT ?vaginal_early) / COUNT(DISTINCT ?g)) / 10 AS ?pct_vaginal_early)
       (ROUND(1000.0 * COUNT(DISTINCT ?cesarean_early) / COUNT(DISTINCT ?g)) / 10 AS ?pct_cesarean_early)
WHERE {
  GRAPH ?g {
    ?birth a sphn:Birth ;
           sphn:hasGestationalAge ?gest_age .
    ?gest_age a sphn:GestationalAgeAtBirth ;
              sphn:hasCode ?gest_code .
    ?birth sphn:hasDeliveryModeCode ?delivery_code .
    ?delivery_code a ?delivery_concept .
  }
  VALUES ?early_root { snomed:396076002 }
  VALUES ?vaginal_root { snomed:224336009 }
  VALUES ?cesarean_root { snomed:224337003 }
  GRAPH <https://biomedit.ch/rdf/sphn-resource/global> {
    ?gest_code rdfs:subClassOf* ?early_root .
    ?delivery_concept rdfs:subClassOf* ?vaginal_root .
    ?delivery_concept rdfs:subClassOf* ?cesarean_root .
  }
  BIND (IF(?gest_code IN (snomed:396076002), 1, 0) AS ?is_early)
  BIND (IF(?delivery_concept IN (snomed:224336009), "vaginal", "cesarean") AS ?delivery_type)
  BIND (IF(?is_early = 1, ?g, ?none) AS ?early_baby)
  BIND (IF(?is_early = 1 && ?delivery_type = "vaginal", ?g, ?none) AS ?vaginal_early)
  BIND (IF(?is_early = 1 && ?delivery_type = "cesarean", ?g, ?none) AS ?cesarean_early)
}

PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>

SELECT (COUNT(DISTINCT ?g) AS ?total_tests)
       (MIN(?first_date) AS ?first_date)
       (MAX(?last_date) AS ?last_date)
WHERE {
  GRAPH ?g {
    ?test a sphn:Diagnosis ;
          sphn:hasSubjectPseudoIdentifier "0042" ;
          sphn:hasReportDateTime ?report_date .
  }
  BIND(?report_date AS ?first_date)
  BIND(?report_date AS ?last_date)
}

