PREFIX sphn: <https://biomedit.ch/rdf/sphn-schema/sphn#>
PREFIX sphn-individual: <https://biomedit.ch/rdf/sphn-schema/sphn/individual#>
PREFIX icd-10-gm: <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/>

CONSTRUCT {
  ?g a sphn:BilledDiagnosis ;
     sphn:hasCode ?code ;
     sphn:hasRank ?rank ;
     sphn:hasRecordDateTime ?recorded ;
     sphn:hasAdministrativeCase ?case ;
     sphn:hasDataProvider ?provider ;
     sphn:hasSourceSystem ?source ;
     sphn:hasSubjectAge ?age ;
     sphn:hasSubjectPseudoIdentifier ?pid .
  ?code a icd-10-gm:C71 .
  ?age a sphn:Age .
}
WHERE {
  GRAPH ?g {
    ?dx a sphn:BilledDiagnosis ;
        sphn:hasRank ?rank ;
        sphn:hasRecordDateTime ?recorded ;
        sphn:hasAdministrativeCase ?case ;
        sphn:hasDataProvider ?provider ;
        sphn:hasSourceSystem ?source ;
        sphn:hasSubjectAge ?age ;
        sphn:hasSubjectPseudoIdentifier ?pid ;
        sphn:hasCode ?code .
  }
  ?code a icd-10-gm:C71 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
}

