  GRAPH ?g {
    ?new_diagnosis a sphn:BilledDiagnosis ;
                   sphn:hasCode ?influenza_code ;
                   sphn:hasSubjectPseudoIdentifier ?pseudo_id .
  }
}
WHERE {
  {
    SELECT DISTINCT(?g AS ?pseudo_id)
    WHERE {
      GRAPH ?g {
        ?patient_record a sphn:AdministrativeCase .
