  BIND(?g AS ?g)
  VALUES ?influenza_code {
    <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/J09>
    <https://biomedit.ch/rdf/sphn-resource/icd-10-gm/J10>
  }
  FILTER EXISTS {
    ?influenza_code a icd-10-gm:J09 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
    ?influenza_code a icd-10-gm:J10 OPTION (inference "https://biomedit.ch/rdf/sphn-resource/global") .
  }
}
